@media(max-width:700px){.monitoring-controls{align-items:stretch;flex-direction:column}.monitoring-search{flex-basis:auto}.monitoring-filter,.monitoring-refresh{justify-content:space-between;padding:0;border:0}.monitoring-filter select,.monitoring-refresh select{flex:1}.monitoring-health-strip{grid-template-columns:1fr}}
